{
  "segment_function": "Examine the role of models, multiplication, and means-end categories in the process of fabrication within the vita activa.",
  "claims": [
    {
      "claim": "The work of fabrication is guided by a model, such as a mental image or blueprint, which precedes the actual work process and exists outside the fabricator.",
      "claim_type": "author_position",
      "supporting_excerpt": "The actual work of fabrication is performed under the guidance of a model in accordance with which the object is constructed. This model can be an image beheld by the eye of the mind or a blueprint in which the image has already found a tentative materialization through work. In either case, what guides the work of fabrication is outside the fabricator and precedes the actual work process in much the same way as the urgencies of the life process within the laborer precede the actual labor process.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "The process of making is entirely determined by the categories of means and end, where the fabricated thing serves as an independent enduring end product.",
      "claim_type": "author_position",
      "supporting_excerpt": "The process of making is itself entirely determined by the categories of means and end. The fabricated thing is an end product in the twofold sense that the production process comes to an end in it (“the process disappears in the product,” as Marx said) and that it is only a means to produce this end.",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [],
  "distinctions": [
    {
      "item_a": "Multiplication",
      "item_b": "Repetition",
      "distinction": "Multiplication multiplies something that already possesses a relatively stable, relatively permanent existence in the world, whereas repetition is urged upon and remains subject to the biological cycle."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": []
}

